+	const uint8_t *end = buf;
+        int err;
+
+	ws_assert(cint);
+
+	if (!buf) {
+#ifdef WS_ASSERT_ENABLED
+		ws_warn_badarg("!buf");
+#endif
+		errno = EINVAL;
+		return false;
